/* Active length of each table = enum's _MAX (sentinel is at index MAX). */
#define CAN_RX_TABLE_LEN_U32 ((U32)CAN_RX_IDX_MAX)
#define CAN_TX_TABLE_LEN_U32 ((U32)CAN_TX_IDX_MAX)

/* =====================================================================
 * Public dispatchers
 *
 * Both can_parse_rx() and can_build_tx() use the same dispatch pattern:
 *   1. NULL-pointer guard on caller-supplied buffers.
 *   2. Lower-bound binary search over the sorted CAN-ID lookup table
 *      to translate id_u32 -> table index in O(log N).
 *   3. Equality check on the found slot to distinguish hit vs miss.
 *   4. On hit, jump through the parallel function-pointer table to the
 *      per-message helper (which owns DLC check + bit packing/unpacking).
 *
 * Why binary search (not switch/if-else chain):
 *   - O(log N) probes vs O(N) worst case; for ~180 RX IDs that's
 *     ~8 comparisons vs up to 180.
 *   - The id array is a separate, cache-friendly U16/U32 array — the
 *     hot loop touches only ~2 cache lines regardless of N.
 *   - Generated code stays flat (no giant switch -> better i-cache).
 *
 * Lower-bound invariant: the target ID, if present, always lies in
 * the half-open range [lo_u32, hi_u32). Each iteration shrinks that
 * window by half, so the loop is guaranteed to terminate in
 * ceil(log2(N)) iterations.
 * =====================================================================*/

/**
 * @brief Decode an incoming CAN frame directly into the phy view.
 * @return CAN_PARSE_OK on success, NULL_PTR / DLC_MISMATCH / UNKNOWN_ID otherwise.
 */
CAN_PARSE_STATUS_te can_parse_rx(U32 id_u32, const U8 *data_au8, U8 dlc_u8,
                                can_dbc_tst *dbc_pst)
{
    U32 lo_u32;   /* Inclusive lower bound of the still-viable index window. */
    U32 hi_u32;   /* Exclusive upper bound — search range is [lo_u32, hi_u32). */
    U32 mid_u32;  /* Probe index for the current iteration. */

    /* Defensive: helper functions dereference both pointers without
     * re-checking, so any NULL must be rejected at the API boundary. */
    if ((data_au8 == NULL) || (dbc_pst == NULL))
    {
        return CAN_PARSE_NULL_PTR;
    }

    /* Initialise the search window to span the whole id table.
     * CAN_RX_TABLE_LEN_U32 == (U32)CAN_RX_IDX_MAX, i.e. one-past-the-last
     * real entry; the table itself has a sentinel slot at that index. */
    lo_u32 = 0U;
    hi_u32 = CAN_RX_TABLE_LEN_U32;
    while (lo_u32 < hi_u32)
    {
        /* Midpoint via shift instead of division — MISRA-friendly and
         * cheaper on cores without a hardware divider. Overflow is not
         * a concern here: the table is far smaller than U32_MAX/2. */
        mid_u32 = (lo_u32 + hi_u32) >> COM_HDR_SHIFT_1_BITS;

        /* Strict `<` (not `<=`) gives the lower-bound variant: when the
         * probe equals the target, we keep the slot in the window by
         * snapping hi_u32 down to mid_u32 — never lo_u32 up past it. */
        if ((U32)can_rx_id_a[mid_u32] < id_u32)
        {
            lo_u32 = mid_u32 + 1U;   /* target lies strictly to the right */
        }
        else
        {
            hi_u32 = mid_u32;        /* target lies at or to the left   */
        }
    }

    /* Loop exits with lo_u32 == hi_u32, pointing at the first slot whose
     * id_u32 >= the requested id (or at CAN_RX_TABLE_LEN_U32 if every
     * stored id is smaller). Equality at that slot means a real hit;
     * anything else means the id isn't in our RX list. */
    if ((lo_u32 < CAN_RX_TABLE_LEN_U32) && ((U32)can_rx_id_a[lo_u32] == id_u32))
    {
        /* Parallel-array dispatch: can_rx_id_a[i] and can_rx_fn_a[i]
         * describe the same message. The per-message helper performs
         * its own DLC check and signal extraction. */
        return can_rx_fn_a[lo_u32](data_au8, dlc_u8, dbc_pst);
    }
    /* Miss: this id is not received by any ECU enabled in this build. */
    return CAN_PARSE_UNKNOWN_ID;
}

/**
 * @brief Encode the phy view of a message directly into a CAN frame.
 * @details On success *dlc_u8 is set from the per-message CAN_<MSG>_DLC
 *          macro (derived from the DBC) so callers don't have to keep
 *          a side table of message lengths.
 * @return CAN_PARSE_OK on success, NULL_PTR / UNKNOWN_ID otherwise.
 */
CAN_PARSE_STATUS_te can_build_tx(U32 id_u32, const can_dbc_tst *dbc_pst,
                                 U8 *data_au8, U8 *dlc_u8)
{
    U32 lo_u32;   /* Inclusive lower bound of the still-viable index window. */
    U32 hi_u32;   /* Exclusive upper bound — search range is [lo_u32, hi_u32). */
    U32 mid_u32;  /* Probe index for the current iteration. */

    /* Defensive: every output buffer plus the source dbc struct must
     * be non-NULL before any helper writes through them. */
    if ((data_au8 == NULL) || (dlc_u8 == NULL) || (dbc_pst == NULL))
    {
        return CAN_PARSE_NULL_PTR;
    }

    /* Same lower-bound search as can_parse_rx(), but over the TX id
     * table. RX/TX tables are independent: a message can be in one,
     * the other, both, or neither depending on which CAN_NODE_* are
     * defined. */
    lo_u32 = 0U;
    hi_u32 = CAN_TX_TABLE_LEN_U32;
    while (lo_u32 < hi_u32)
    {
        /* Midpoint via right-shift; see can_parse_rx() for rationale. */
        mid_u32 = (lo_u32 + hi_u32) >> COM_HDR_SHIFT_1_BITS;
        if ((U32)can_tx_id_a[mid_u32] < id_u32)
        {
            lo_u32 = mid_u32 + 1U;   /* target lies strictly to the right */
        }
        else
        {
            hi_u32 = mid_u32;        /* target lies at or to the left   */
        }
    }

    /* Equality check on the converged slot decides hit vs miss. */
    if ((lo_u32 < CAN_TX_TABLE_LEN_U32) && ((U32)can_tx_id_a[lo_u32] == id_u32))
    {
        /* Helper packs signals into data_au8 and writes the DLC. */
        return can_tx_fn_a[lo_u32](dbc_pst, data_au8, dlc_u8);
    }
    /* Miss: this ECU doesn't transmit the requested ID. */
    return CAN_PARSE_UNKNOWN_ID;
}

